const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

const isLiving = (cell: Cell, livingCells: Cell[]): boolean =>
  livingCells.some(([x, y]) => x === cell[0] && y === cell[1]);

const bornCells = (livingCells: Cell[]): Cell[] =>
  livingCells
    .flatMap(neighborsOf)
    .filter(
      (candidate) =>
        !isLiving(candidate, livingCells) &&
        countLivingNeighbors(candidate, livingCells) === 3,
    );

export const nextGeneration = (livingCells: Cell[]): Cell[] => [
  ...livingCells.filter((cell) =>
    survives(countLivingNeighbors(cell, livingCells)),
  ),
  ...bornCells(livingCells),
];
